function Invoke-CobaltSocksImpact{param($Paths);$t=Get-CobaltSocksTimeline
$ds=Join-Path $Paths.Backup 'Users\Public\Music\ds.exe';New-CobaltSocksDecoy $ds 'LockBit ds.exe filename canary' '59c9d10f06f8cb2049df39fb4870a81999fd3f8a79717df9b309fadeb5f26ef9';$psexec=Join-Path $Paths.Backup 'Users\Public\Music\PsExec.exe';New-CobaltSocksDecoy $psexec 'PsExec process-name canary'
$scripts=@{
'SETUP.bat'='REM net session | REM net share share$=%PUBLIC%\Music /GRANT:Everyone,READ /Y';'WMI.bat'='REM wmic /node:CANARY process call create "bitsadmin transfer ds ..."';'COPY.bat'='REM PsExec.exe @comps1.txt cmd /c COPY \\CANARY\share$\ds.exe';'EXE1.bat'='REM PsExec.exe @comps1.txt cmd /c ds.exe -pass REDACTED';'EXE.bat'='REM redundant LockBit execution disabled';'WMI1.bat'='REM wmic /node:@comps1.txt process call create "bitsadmin ... ds.exe"';'COPY1.bat'='REM redundant PsExec copy disabled';'DEF.bat'='REM Windows Defender modification disabled';'RDP.bat'='REM RDP setting modification disabled'}
foreach($name in $scripts.Keys){Write-CobaltSocksFile(Join-Path $Paths.Backup "Users\Public\Music\$name")"@echo off`nREM COBALTSOCKS CANARY`n$($scripts[$name])`necho No remote or destructive action" 'inert deployment batch' $t.Impact}
foreach($targetHost in @('DC01','FILE01','BACKUP01','APP01','WS001')){$d=Join-Path $Paths.Impact $targetHost;New-Item $d -ItemType Directory -Force|Out-Null;New-CobaltSocksDecoy(Join-Path $d 'PSEXESVC.exe')'PsExec service filename canary';Copy-Item $ds(Join-Path $d 'ds.exe')-Force;foreach($n in @('operations.docx','backup.vbk')){Write-CobaltSocksFile(Join-Path $d $n)"Generated intact original $targetHost/$n" 'generated source' $t.Impact;Write-CobaltSocksFile(Join-Path $d "$n.LOCKBIT-CANARY")'Marker only; no encryption.' 'impact marker' $t.Impact.AddMinutes(90)};Write-CobaltSocksFile(Join-Path $d 'LOCKBIT-CANARY.README.txt')'Forensic canary only. No payment or contact channel.' 'inert note' $t.Complete}
Write-CobaltSocksFile (Join-Path $Paths.Evidence 'deployment-events.json') (@{share='share$';realShare=$false;methods=@('WMI','BITSAdmin','PsExec');remoteTransfer=$false;serviceEvents=@{EventId=7045;ServiceName='PSEXESVC';installed=$false};targetScope='generated local host trees';errorsRepresented=$true;wallpaperChanged=$false;encryption=$false}|ConvertTo-Json -Depth 6) 'two-hour redundant deployment telemetry' $t.Impact
Add-CobaltSocksTimeline $t.Impact 'Impact' 'SETUP/WMI/COPY/EXE/DEF/RDP scripts and ds.exe were staged on the backup-host canary.' @{realShare=$false;securityChanged=$false};Add-CobaltSocksTimeline $t.Complete 'Impact' 'Two-hour WMI/BITS/PsExec deployment completed across generated hosts using signed decoys and marker files.' @{remoteExecution=$false;encryption=$false;wallpaperChanged=$false}}
